// Dynamic state is delivered independently: a title change must never
// re-materialize all stable memory through the host's aggregate context.
let splitMemoryState = false
ctx.effect(() => {
  const dispose = installDynamicMemoryState(ctx, agent => {
    const runtime = getRuntime()
    return renderSnapshot(runtime, store, agent, counter, ctx.sessionTitle, writeGap, 'dynamic')
  })
  splitMemoryState = true
  return () => { splitMemoryState = false; dispose() }
}, 'dsh-memory-evolve: isolated dynamic state')
